              <button
                type="button"
                onClick={() => navigate(-1)}
                className="text-slate-600 hover:text-slate-800 px-4 py-2.5 rounded-lg border border-slate-200 hover:border-slate-300 text-sm font-medium transition-colors"
              >
                Cancel
              </button>
            </div>
          </form>
        </div>
      </main>
    </div>
  );
};

import React, { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { apiClient } from "../../api/apiClient";
import { authApi } from "../../api/authApi";

// ─── Customer session management ─────────────────────────────────────────────

const CUSTOMER_KEY = "legalease_customer_user";

export interface CustomerUser {
  userId: number;
  name: string;
  email: string;
  role: string;
}

export const customerAuth = {
  getUser: (): CustomerUser | null => {
    try {
      const raw = localStorage.getItem(CUSTOMER_KEY);
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  },
  setUser: (user: CustomerUser) => localStorage.setItem(CUSTOMER_KEY, JSON.stringify(user)),
  logout: () => {
    localStorage.removeItem(CUSTOMER_KEY);
    authApi.logoutAll();
  },
  isLoggedIn: () => {
    const u = customerAuth.getUser();
    return !!(u && u.role?.toLowerCase() === "customer");
  },
};

// ─── CustomerLoginPage ────────────────────────────────────────────────────────

export const CustomerLoginPage: React.FC = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (customerAuth.isLoggedIn()) navigate("/my-requests", { replace: true });
