test('TC-C2-04 actual careers page published Senior Counsel',async({page})=>run('TC-C2-04',page,async()=>{const career=JSON.parse(fs.readFileSync('/private/tmp/qmse-history-control/career.json','utf8'));expect(career.created).toBe(201);await page.goto('/careers');await expect(page.getByText('Senior Counsel',{exact:true})).toBeVisible();return {api201:true,actualPublicPageVisible:true};},'Real local API and isolated PostgreSQL career fixture; no API interception.'));
test('TC-C4-06 real login token and logout',async({page})=>run('TC-C4-06',page,async()=>{const {password}=JSON.parse(fs.readFileSync('/private/tmp/qmse-history-control/settings.json','utf8'));await page.goto('/login');await page.locator('#email').fill('qmse-history-admin@example.test');await page.locator('#password').fill(password);await page.getByRole('button',{name:'Sign In',exact:true}).click();await expect(page).not.toHaveURL(/\/login$/);expect(await page.evaluate(()=>!!localStorage.getItem('token'))).toBe(true);const logout=page.getByRole('button',{name:/logout/i}).first();await logout.click();await expect(page).toHaveURL(/\/login$/);expect(await page.evaluate(()=>localStorage.getItem('token'))).toBeNull();return {loginSuccessful:true,tokenStored:true,logoutClicked:true,tokenCleared:true,url:page.url()};},'Actual React login/logout and API-backed authentication against fresh PostgreSQL. Credentials/JWT omitted.'));
